#include <stdio.h>
#include <stdlib.h>

typedef int ElemType;
typedef struct LNode {
    ElemType       data;
    struct LNode  *next;
} LNode, *LinkList;

int CreateTail(LinkList *L, const ElemType a[], int n)
{
    LNode *tail, *s;
    int i;
    *L = (LinkList)malloc(sizeof(LNode));   /* 头结点 */
    if (*L == NULL) return 0;
    (*L)->next = NULL;                      /* 空表 */
    tail = *L;
    for (i = 0; i < n; i++) {
        s = (LNode *)malloc(sizeof(LNode));
        if (s == NULL) return 0;
        s->data = a[i];
        s->next = NULL;
        tail->next = s;                     /* 挂到表尾 */
        tail = s;                           /* 尾指针后移 */
    }
    return 1;
}

void ListTraverse(LinkList L)
{
    LNode *p = L->next;                     /* 跳过头结点 */
    printf("head");
    while (p != NULL) { printf(" -> %d", p->data); p = p->next; }
    printf(" -> NULL\n");
}

void DestroyList(LinkList *L)
{
    LNode *p = *L, *q;
    while (p != NULL) { q = p->next; free(p); p = q; }
    *L = NULL;
}

int main(void)
{
    LinkList L = NULL;
    ElemType a[6] = {11, 22, 33, 44, 55, 66};
    if (!CreateTail(&L, a, 6)) { printf("malloc failed\n"); return 1; }
    ListTraverse(L);
    printf("表空? %d\n", L->next == NULL);
    DestroyList(&L);
    printf("destroyed -> %s\n", L == NULL ? "NULL" : "?");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef char ElemType;
typedef struct LNode { ElemType data; struct LNode *next; } LNode, *LinkList;

/* 返回第 i 个结点的指针，头结点算第 0 个；越界返回 NULL */
LNode *GetElemP(LinkList L, int i)
{
    LNode *p = L;
    int j = 0;
    while (p != NULL && j < i) { p = p->next; j++; }
    if (i < 0 || j > i) return NULL;
    return p;
}

int ListInsert(LinkList L, int i, ElemType e)
{
    LNode *p = GetElemP(L, i - 1), *s;   /* 找第 i-1 个结点 */
    if (p == NULL) return 0;
    s = (LNode *)malloc(sizeof(LNode));
    if (s == NULL) return 0;
    s->data = e;
    s->next = p->next;    /* ① 先接 */
    p->next = s;          /* ② 后断 */
    return 1;
}

int ListDelete(LinkList L, int i, ElemType *e)
{
    LNode *p = GetElemP(L, i - 1), *q;
    if (p == NULL || p->next == NULL) return 0;
    q = p->next;
    *e = q->data;
    p->next = q->next;
    free(q);
    return 1;
}

int main(void)
{
    LNode head, *p, *q;
    LinkList L = &head;
    ElemType e = 0;
    int i;

    head.data = '#'; head.next = NULL;          /* 头结点 */
    for (i = 1; i <= 5; i++) ListInsert(L, i, (ElemType)('A' + i - 1));

    printf("create      :");
    for (p = L->next; p != NULL; p = p->next) printf(" %c", p->data);
    ListInsert(L, 3, 'X');
    printf("\ninsert X @3 :");
    for (p = L->next; p != NULL; p = p->next) printf(" %c", p->data);
    ListDelete(L, 2, &e);
    printf("\ndelete @2=%c :", e);
    for (p = L->next; p != NULL; p = p->next) printf(" %c", p->data);
    printf("\n第3个元素 = %c\n", GetElemP(L, 3)->data);

    p = L->next;                                /* 释放所有数据结点 */
    while (p != NULL) { q = p->next; free(p); p = q; }
    L->next = NULL;
    printf("all data nodes freed, 表空? %d\n", L->next == NULL);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef int ElemType;
typedef struct DuLNode {
    ElemType        data;
    struct DuLNode *prior;
    struct DuLNode *next;
} DuLNode, *DuLinkList;

int InitDuList(DuLinkList *L)
{
    *L = (DuLinkList)malloc(sizeof(DuLNode));
    if (*L == NULL) return 0;
    (*L)->prior = (*L)->next = *L;   /* 空的双向循环链表：头结点自环 */
    return 1;
}

int InsertAfter(DuLinkList p, ElemType e)   /* 在 p 之后插入 */
{
    DuLNode *s = (DuLNode *)malloc(sizeof(DuLNode));
    if (s == NULL) return 0;
    s->data = e;
    s->prior = p;
    s->next  = p->next;
    p->next->prior = s;      /* 必须先改后继的 prior */
    p->next = s;             /* 再改前驱的 next */
    return 1;
}

int DeleteNode(DuLinkList p)                /* p 由调用方保证不是头结点 */
{
    if (p == NULL) return 0;
    p->prior->next = p->next;
    p->next->prior = p->prior;
    free(p);
    return 1;
}

int main(void)
{
    DuLinkList L = NULL, p;
    DuLNode *q;
    int i;
    if (!InitDuList(&L)) { printf("malloc failed\n"); return 1; }

    p = L;
    for (i = 1; i <= 5; i++) { InsertAfter(p, i * 10); p = p->next; }

    printf("空表判断 L->next==L ? %d\n", L->next == L);
    printf("正向:");
    for (p = L->next; p != L; p = p->next)  printf(" %d", p->data);
    printf("\n反向:");
    for (p = L->prior; p != L; p = p->prior) printf(" %d", p->data);
    printf("\n");

    p = L->next->next->next;   /* 第 3 个数据结点 */
    printf("待删除 = %d\n", p->data);
    DeleteNode(p);
    printf("删后正向:");
    for (p = L->next; p != L; p = p->next)  printf(" %d", p->data);
    printf("\n删后反向:");
    for (p = L->prior; p != L; p = p->prior) printf(" %d", p->data);
    printf("\n");

    p = L->next;               /* 销毁：沿 next 走一圈回到头结点 */
    while (p != L) { q = p->next; free(p); p = q; }
    free(L);
    printf("freed\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct CNode { int no; struct CNode *next; } CNode;

int main(void)
{
    int n = 8, m = 3, i;
    CNode *L, *p, *prev, *s, *q;

    L = (CNode *)malloc(sizeof(CNode));
    if (L == NULL) return 1;
    L->no = 1; L->next = L;        /* 1 号自己成环 */
    p = L;
    for (i = 2; i <= n; i++) {     /* 尾插建环 */
        s = (CNode *)malloc(sizeof(CNode));
        if (s == NULL) return 1;
        s->no = i; s->next = L;
        p->next = s; p = s;
    }

    printf("n=%d m=%d 出列顺序:", n, m);
    prev = p;                      /* prev 指向尾结点 */
    p = L;                         /* p 指向 1 号 */
    while (p->next != p) {         /* 环中不止一个结点 */
        for (i = 1; i < m; i++) { prev = p; p = p->next; }
        printf(" %d", p->no);
        prev->next = p->next;      /* 摘掉 p */
        q = p; p = p->next; free(q);
    }
    printf(" %d(最后)\n", p->no);
    free(p);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 20
typedef int DataType;

typedef struct {
    DataType list[MAXSIZE];
    int size;
} SeqList;

/* 在下标 i（0 <= i <= size）之前插入 x，返回移动次数；失败返回 -1 */
int seqInsert(SeqList *L, int i, DataType x)
{
    int j, moved = 0;

    if (L->size >= MAXSIZE) {
        return -1;                     /* 表满 */
    }
    if (i < 0 || i > L->size) {
        return -1;                     /* 位置非法 */
    }
    for (j = L->size; j > i; j--) {    /* 从后往前挪，否则覆盖数据 */
        L->list[j] = L->list[j - 1];
        moved++;
    }
    L->list[i] = x;
    L->size++;
    return moved;
}

/* 删除下标 i（0 <= i < size）的元素，值由 *x 带出，返回移动次数；失败返回 -1 */
int seqDelete(SeqList *L, int i, DataType *x)
{
    int j, moved = 0;

    if (i < 0 || i >= L->size) {
        return -1;
    }
    *x = L->list[i];
    for (j = i + 1; j < L->size; j++) { /* 从前往后挪 */
        L->list[j - 1] = L->list[j];
        moved++;
    }
    L->size--;
    return moved;
}

static void show(const char *tag, const SeqList *L)
{
    int i;

    printf("%s", tag);
    for (i = 0; i < L->size; i++) {
        printf(" %d", L->list[i]);
    }
    printf("\n");
}

int main(void)
{
    SeqList L;
    DataType got = 0;
    int i, moved;

    L.size = 0;
    for (i = 1; i <= 5; i++) {
        seqInsert(&L, L.size, i * 10);  /* 每次插在末尾，移动 0 次 */
    }
    show("初始顺序表:", &L);

    moved = seqInsert(&L, 1, 99);
    printf("在下标 1 前插入 99，移动 %d 个元素\n", moved);
    show("插入后:", &L);

    moved = seqDelete(&L, 0, &got);
    printf("删除下标 0，取出 %d，移动 %d 个元素\n", got, moved);
    show("删除后:", &L);

    printf("越界插入下标 99 返回 %d\n", seqInsert(&L, 99, 1));
    printf("越界删除下标 99 返回 %d\n", seqDelete(&L, 99, &got));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef int DataType;

typedef struct Node {
    DataType data;
    struct Node *next;
} Node;

/* 建带头结点的单链表，按数组顺序尾插 */
Node *createList(const DataType a[], int n)
{
    Node *head = (Node *)malloc(sizeof(Node));
    Node *tail;
    Node *p;
    int i;

    if (head == NULL) {
        return NULL;
    }
    head->next = NULL;
    tail = head;
    for (i = 0; i < n; i++) {
        p = (Node *)malloc(sizeof(Node));
        if (p == NULL) {
            return head;
        }
        p->data = a[i];
        p->next = NULL;
        tail->next = p;
        tail = p;
    }
    return head;
}

/* 在第 i 个数据元素（i 从 1 开始）之前插入 x；成功返回 0，越界返回 1，分配失败返回 2 */
int listInsert(Node *head, int i, DataType x)
{
    Node *pre = head;
    Node *p;
    int k = 0;

    while (pre != NULL && k < i - 1) {   /* 走到第 i-1 个结点，即前驱 */
        pre = pre->next;
        k++;
    }
    if (pre == NULL) {
        return 1;
    }
    p = (Node *)malloc(sizeof(Node));
    if (p == NULL) {
        return 2;
    }
    p->data = x;
    p->next = pre->next;                 /* ① 先接 */
    pre->next = p;                       /* ② 后断 */
    return 0;
}

/* 删除第 i 个数据元素，值由 *x 带出；成功返回 0，越界返回 1 */
int listDelete(Node *head, int i, DataType *x)
{
    Node *pre = head;
    Node *p;
    int k = 0;

    while (pre->next != NULL && k < i - 1) {
        pre = pre->next;
        k++;
    }
    if (pre->next == NULL) {
        return 1;
    }
    p = pre->next;
    *x = p->data;                        /* 先取值 */
    pre->next = p->next;                 /* 再摘链 */
    free(p);                             /* 最后释放 */
    return 0;
}

static void showList(const char *tag, const Node *head)
{
    const Node *p;

    printf("%s", tag);
    for (p = head->next; p != NULL; p = p->next) {
        printf(" %d", p->data);
    }
    printf("\n");
}

static void freeList(Node *head)
{
    Node *p = head;
    Node *q;

    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }
}

int main(void)
{
    DataType a[5] = { 11, 22, 33, 44, 55 };
    DataType got = 0;
    Node *head = createList(a, 5);

    if (head == NULL) {
        printf("建表失败\n");
        return 1;
    }
    showList("初始链表:", head);

    printf("在第 2 个元素前插入 99，返回 %d\n", listInsert(head, 2, 99));
    showList("插入后:", head);

    printf("删除第 4 个元素，返回 %d\n", listDelete(head, 4, &got));
    printf("取出的值是 %d\n", got);
    showList("删除后:", head);

    printf("插入到第 99 位（越界），返回 %d\n", listInsert(head, 99, 1));
    printf("删除第 99 个（越界），返回 %d\n", listDelete(head, 99, &got));

    freeList(head);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* 不带头结点：必须返回新的头指针，否则调用方拿不到新表头 */
Node *insertFrontPlain(Node *head, int x)
{
    Node *p = (Node *)malloc(sizeof(Node));

    if (p == NULL) {
        return head;
    }
    p->data = x;
    p->next = head;
    return p;
}

/* 带头结点：头结点永远不动，函数可以是 void，与表中插入代码完全一致 */
void insertFrontGuarded(Node *head, int x)
{
    Node *p = (Node *)malloc(sizeof(Node));

    if (p == NULL) {
        return;
    }
    p->data = x;
    p->next = head->next;
    head->next = p;
}

static void show(const char *tag, const Node *p)
{
    printf("%s", tag);
    for (; p != NULL; p = p->next) {
        printf(" %d", p->data);
    }
    printf("\n");
}

static void freeAll(Node *p)
{
    Node *q;

    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }
}

int main(void)
{
    Node *plain = NULL;                              /* 不带头结点：空表就是 NULL */
    Node *guarded = (Node *)malloc(sizeof(Node));
    int i;

    if (guarded == NULL) {
        printf("分配失败\n");
        return 1;
    }
    guarded->data = -1;                              /* 头结点的 data 不存数据，这里用作标记 */
    guarded->next = NULL;

    printf("插入前判空：不带头结点 head == NULL → %s\n", plain == NULL ? "空表" : "非空");
    printf("插入前判空：带头结点 head->next == NULL → %s\n",
           guarded->next == NULL ? "空表" : "非空");

    for (i = 1; i <= 3; i++) {
        plain = insertFrontPlain(plain, i * 10);     /* 必须接收返回值 */
        insertFrontGuarded(guarded, i * 10);         /* 头指针始终不变 */
    }

    show("不带头结点（head 被改了 3 次）:", plain);
    show("带头结点（从 head->next 起）  :", guarded->next);
    printf("头结点自身的 data = %d（不存数据）\n", guarded->data);

    freeAll(plain);
    freeAll(guarded);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* 建一个空的带头结点循环链表，返回的指针既是头结点也是 rear（此时二者重合） */
Node *createEmpty(void)
{
    Node *head = (Node *)malloc(sizeof(Node));

    if (head == NULL) {
        return NULL;
    }
    head->data = 0;
    head->next = head;               /* 空表：自己指自己 */
    return head;
}

/* 入队 = 尾插，O(1)：不需要遍历找尾 */
int pushBack(Node **rear, int x)
{
    Node *p = (Node *)malloc(sizeof(Node));

    if (p == NULL) {
        return 1;
    }
    p->data = x;
    p->next = (*rear)->next;         /* 新结点的后继 = 头结点 */
    (*rear)->next = p;
    *rear = p;                       /* 尾指针后移 */
    return 0;
}

/* 出队 = 头删，O(1)：头结点固定在 (*rear)->next */
int popFront(Node **rear, int *x)
{
    Node *head = (*rear)->next;
    Node *p;

    if (head == *rear) {
        return 0;                    /* 空表 */
    }
    p = head->next;
    *x = p->data;
    head->next = p->next;
    if (p == *rear) {
        *rear = head;                /* 删的是最后一个结点，rear 必须退回头结点 */
    }
    free(p);
    return 1;
}

int main(void)
{
    Node *rear = createEmpty();
    Node *head, *p;
    int i, got = 0;

    if (rear == NULL) {
        printf("分配失败\n");
        return 1;
    }
    printf("空表判定 rear->next == rear → %s\n", rear->next == rear ? "真" : "假");

    for (i = 1; i <= 4; i++) {
        pushBack(&rear, i * 100);
    }

    head = rear->next;
    printf("入队 4 次后:");
    for (p = head->next; p != head; p = p->next) {
        printf(" %d", p->data);
    }
    printf("\n");
    printf("首元素 = %d，尾元素 = %d\n", head->next->data, rear->data);

    while (popFront(&rear, &got) == 1) {
        printf("出队 %d\n", got);
    }
    printf("全部出队后 rear->next == rear → %s\n", rear->next == rear ? "真" : "假");

    free(rear);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct DNode {
    int data;
    struct DNode *prior;
    struct DNode *next;
} DNode;

/* 建带头结点的双向循环链表，按数组顺序尾插 */
DNode *createDList(const int a[], int n)
{
    DNode *head = (DNode *)malloc(sizeof(DNode));
    DNode *tail;
    DNode *p;
    int i;

    if (head == NULL) {
        return NULL;
    }
    head->prior = head;
    head->next = head;
    tail = head;
    for (i = 0; i < n; i++) {
        p = (DNode *)malloc(sizeof(DNode));
        if (p == NULL) {
            return head;
        }
        p->data = a[i];
        p->next = tail->next;        /* = head */
        p->prior = tail;
        tail->next->prior = p;       /* head->prior = p */
        tail->next = p;
        tail = p;
    }
    return head;
}

/* 在结点 p 之后插入 x：四步，③ 必须早于 ④ */
int insertAfter(DNode *p, int x)
{
    DNode *s = (DNode *)malloc(sizeof(DNode));

    if (s == NULL) {
        return 1;
    }
    s->data = x;
    s->prior = p;                    /* ① */
    s->next = p->next;               /* ② */
    p->next->prior = s;              /* ③ */
    p->next = s;                     /* ④ */
    return 0;
}

/* 删除数据结点 p：两步，O(1)，不需要找前驱 */
void deleteNode(DNode *p)
{
    p->prior->next = p->next;
    p->next->prior = p->prior;
    free(p);
}

static void showForward(const DNode *head)
{
    const DNode *p;

    printf("正向:");
    for (p = head->next; p != head; p = p->next) {
        printf(" %d", p->data);
    }
    printf("\n");
}

static void showBackward(const DNode *head)
{
    const DNode *p;

    printf("反向:");
    for (p = head->prior; p != head; p = p->prior) {
        printf(" %d", p->data);
    }
    printf("\n");
}

int main(void)
{
    int a[4] = { 1, 2, 3, 4 };
    DNode *head = createDList(a, 4);
    DNode *p;

    if (head == NULL) {
        printf("分配失败\n");
        return 1;
    }
    showForward(head);

    p = head->next->next;                    /* 值为 2 的结点 */
    printf("在结点 %d 之后插入 99，返回 %d\n", p->data, insertAfter(p, 99));
    showForward(head);
    showBackward(head);                      /* 反向能走通，说明 prior 链也正确 */

    for (p = head->next; p != head && p->data != 3; p = p->next) {
        /* 找值为 3 的结点 */
    }
    if (p != head) {
        deleteNode(p);                       /* 拿到结点自己就能删，O(1) */
    }
    showForward(head);

    p = head->next;                          /* 释放整条循环链表 */
    while (p != head) {
        DNode *q = p->next;
        free(p);
        p = q;
    }
    free(head);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 8
typedef int DataType;

typedef struct {
    DataType data;
    int cursor;                    /* 下一个单元的下标，0 表示链尾 */
} SNode;

static SNode pool[MAXSIZE];
static int freeHead;

/* 把 1..MAXSIZE-1 号单元串成备用链表，0 号作头结点 */
void poolInit(void)
{
    int i;

    pool[0].cursor = 0;            /* 初始为空表 */
    for (i = 1; i < MAXSIZE - 1; i++) {
        pool[i].cursor = i + 1;
    }
    pool[MAXSIZE - 1].cursor = 0;
    freeHead = 1;
}

/* 从备用链摘一个单元，无可用返回 0 */
int allocNode(void)
{
    int i = freeHead;

    if (i != 0) {
        freeHead = pool[i].cursor;
    }
    return i;
}

/* 把单元归还备用链（头插） */
void freeNode(int i)
{
    pool[i].cursor = freeHead;
    freeHead = i;
}

/* 尾插 x；备用链空返回 -1 */
int slPushBack(DataType x)
{
    int tail = 0, i;

    while (pool[tail].cursor != 0) {
        tail = pool[tail].cursor;
    }
    i = allocNode();
    if (i == 0) {
        return -1;
    }
    pool[i].data = x;
    pool[i].cursor = 0;
    pool[tail].cursor = i;
    return 0;
}

/* 删除第一个值等于 x 的单元；未找到返回 1 */
int slRemove(DataType x)
{
    int pre = 0, cur;

    cur = pool[pre].cursor;
    while (cur != 0 && pool[cur].data != x) {
        pre = cur;
        cur = pool[cur].cursor;
    }
    if (cur == 0) {
        return 1;
    }
    pool[pre].cursor = pool[cur].cursor;
    freeNode(cur);
    return 0;
}

static void show(const char *tag)
{
    int k;

    printf("%s", tag);
    for (k = pool[0].cursor; k != 0; k = pool[k].cursor) {
        printf(" [%d]=%d", k, pool[k].data);
    }
    printf("\n");
}

int main(void)
{
    DataType vals[9] = { 10, 20, 30, 40, 50, 60, 70, 80, 90 };
    int i;

    poolInit();
    for (i = 0; i < 9; i++) {
        if (slPushBack(vals[i]) != 0) {
            printf("第 %d 个元素 %d 插入失败：备用链已空（MAXSIZE=%d，可存 %d 个数据）\n",
                   i + 1, vals[i], MAXSIZE, MAXSIZE - 1);
            break;
        }
    }
    show("静态链表内容:");

    printf("删除 30 返回 %d\n", slRemove(30));
    show("删除后:");
    printf("备用链头 freeHead = %d（刚回收的 3 号单元）\n", freeHead);

    printf("删除 999 返回 %d（未找到）\n", slRemove(999));
    return 0;
}

#include <stdio.h>

#define MAXSIZE 30

/* 两个递增有序表合并为递增有序表，相等时只收一份；返回结果长度 */
int mergeOrdered(const int *a, int na, const int *b, int nb, int *c)
{
    int i = 0, j = 0, k = 0;

    while (i < na && j < nb) {
        if (a[i] < b[j]) {
            c[k++] = a[i++];
        } else if (a[i] > b[j]) {
            c[k++] = b[j++];
        } else {
            c[k++] = a[i];             /* 相等：收一份，两个指针同时前进 */
            i++;
            j++;
        }
    }
    while (i < na) {
        c[k++] = a[i++];               /* A 剩余整段接上 */
    }
    while (j < nb) {
        c[k++] = b[j++];               /* B 剩余整段接上 */
    }
    return k;
}

/* 递增有序数组就地去重（快慢指针），返回新长度 */
int uniqueInPlace(int *a, int n)
{
    int i, k = 0;

    for (i = 0; i < n; i++) {
        if (k == 0 || a[i] != a[k - 1]) {
            a[k++] = a[i];             /* 只与结果区最后一个比较 */
        }
    }
    return k;
}

static void show(const char *tag, const int *a, int n)
{
    int i;

    printf("%s", tag);
    for (i = 0; i < n; i++) {
        printf(" %d", a[i]);
    }
    printf("\n");
}

int main(void)
{
    int a[7] = { 1, 3, 3, 5, 7, 9, 11 };
    int b[6] = { 2, 3, 4, 9, 12, 15 };
    int c[MAXSIZE];
    int dup[6] = { 4, 4, 4, 7, 7, 9 };
    int nc, nd;

    show("A:", a, 7);
    show("B:", b, 6);

    nc = mergeOrdered(a, 7, b, 6, c);
    printf("合并后长度 %d\n", nc);
    show("C(合并):", c, nc);

    nc = uniqueInPlace(c, nc);         /* A 内部本身有重复 3，需再去一次 */
    printf("去重后长度 %d\n", nc);
    show("C(去重):", c, nc);

    nd = uniqueInPlace(dup, 6);
    printf("D 去重后长度 %d\n", nd);
    show("D:", dup, nd);
    return 0;
}

