## 套路一：就地逆置（头插法）

```c
void reverseList(Node *head)
{
    Node *p = head->next;
    Node *q;

    head->next = NULL;             /* 先把链表「摘下来」，头结点自成空表 */
    while (p != NULL) {
        q = p->next;               /* ① 先存后继，这一步之后 p 才能安全断链 */
        p->next = head->next;      /* ② 把 p 头插到 head 之后 */
        head->next = p;
        p = q;                     /* ③ 继续处理下一个 */
    }
}
```

时间 O(n)、**额外空间 O(1)**，这是「就地」的含义。逆置后原表尾变成表头。
另一种做法是把值倒着填回原位置，但那需要 O(n) 辅助数组，不算就地。

## 套路二：约瑟夫环

n 个人围成一圈，从第 1 个人开始报数，报到 m 的人出列，然后从下一个人重新报数，求出列次序。
用**循环单链表**表示圈，关键是要维护一个 **pre 指针始终指向 p 的前驱**，
因为单链表摘掉 p 必须通过 p 的前驱改向：

```c
pre = tail;  p = head;
while (left > 0) {
    for (i = 1; i < m; i++) { pre = p; p = p->next; }   /* 报数 m-1 次 */
    printf("%d ", p->data);
    pre->next = p->next;                                /* 摘链 */
    dead = p;  p = p->next;  free(dead);                /* 先移走 p 再 free */
    left--;
}
```

时间复杂度 O(n·m)。n=7、m=3 的经典答案是 3 6 2 7 5 1 4。

## 为什么必须「先存后继」

所有链表操作里，**一旦某个指针被改写，它原来指向的结点就可能永久失联**（无法访问、也无法 free）。
所以固定动作是：改 `p->next` 之前先 `q = p->next`；改 `pre->next` 之前先把 `p` 存好。
这条纪律在逆置、删除、合并、拆分里全都适用，也是链表题最常见的丢分点。

examples.code:
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* 就地逆置带头结点的单链表：头插法，O(n) 时间 O(1) 空间 */
void reverseList(Node *head)
{
    Node *p = head->next;
    Node *q;

    head->next = NULL;                 /* 先摘下来，头结点自成空表 */
    while (p != NULL) {
        q = p->next;                   /* ① 先存后继 */
        p->next = head->next;          /* ② 头插 */
        head->next = p;
        p = q;                         /* ③ 前进 */
    }
}

/* 约瑟夫环：n 人围圈，从 1 号开始报数，数到 m 出列，打印出列次序 */
void josephus(int n, int m)
{
    Node *head = (Node *)malloc(sizeof(Node));
    Node *tail, *p, *pre, *dead;
    int i, left;

    if (head == NULL) {
        printf("分配失败\n");
        return;
    }
    head->data = 1;
    head->next = NULL;
    tail = head;
    for (i = 2; i <= n; i++) {
        p = (Node *)malloc(sizeof(Node));
        if (p == NULL) {
            break;
        }
        p->data = i;
        p->next = NULL;
        tail->next = p;
        tail = p;
    }
    tail->next = head;                 /* 成环 */

    printf("出列次序:");
    pre = tail;                        /* pre 始终指向 p 的前驱 */
    p = head;
    left = n;
    while (left > 0) {
        for (i = 1; i < m; i++) {      /* 报数 m-1 次，p 落到第 m 个人 */
            pre = p;
            p = p->next;
        }
        printf(" %d", p->data);
        pre->next = p->next;           /* 摘链 */
        dead = p;
        p = p->next;                   /* 先把 p 移走 */
        free(dead);                    /* 再释放 */
        left--;
    }
    printf("\n");
}

static void show(const char *tag, const Node *head)
{
    const Node *p;

    printf("%s", tag);
    for (p = head->next; p != NULL; p = p->next) {
        printf(" %d", p->data);
    }
    printf("\n");
}

int main(void)
{
    Node *head = (Node *)malloc(sizeof(Node));
    Node *p, *q;
    int i;

    if (head == NULL) {
        printf("分配失败\n");
        return 1;
    }
    head->next = NULL;
    for (i = 5; i >= 1; i--) {         /* 头插建表，得到 1 2 3 4 5 */
        p = (Node *)malloc(sizeof(Node));
        if (p == NULL) {
            return 1;
        }
        p->data = i;
        p->next = head->next;
        head->next = p;
    }
    show("逆置前:", head);
    reverseList(head);
    show("逆置后:", head);

    josephus(7, 3);

    p = head;                          /* 释放逆置后的普通单链表 */
    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }
    return 0;
}
